export const GAUSSIAN_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/gaussian-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getGaussianStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(GAUSSIAN_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
